import Image, { type ImageProps } from "next/image";
import { imageSizes } from "@/data/image-sizes";

type Props = Omit<ImageProps, "width" | "height" | "src"> & { src: string };

/**
 * next/image for photos in /public: looks up the intrinsic size generated by
 * `npm run image-sizes`, so the browser reserves the right space and only
 * downloads a resized AVIF/WebP instead of the full-size original.
 */
export function Photo({ src, alt, ...props }: Props) {
  const size = imageSizes[src];
  if (!size) {
    // Unknown file (e.g. added without regenerating sizes): still optimise it.
    return <Image src={src} alt={alt} width={1200} height={1500} {...props} />;
  }
  return <Image src={src} alt={alt} width={size[0]} height={size[1]} {...props} />;
}
